mapper.update:
update course
set is_delete=1
where course_id = #{id}

mapper.select:
SELECT c.classify_id as classifyId, c.course_id as courseId, c.course_label as courseLabel, c.create_time createTime, c.details, c.img, c.banner_img as bannerImg, c.is_delete as isDelete, c.msg_type msgType, c.msg_url as msgUrl, c.pay_num as payNum, c.price, c.jifen, c.status, c.title, c.title_img as titleImg, c.update_time as updateTime FROM course c WHERE c.is_delete = 0 and c.status=1
and c.title LIKE #{title}
order by create_time desc

SELECT *, (select count(*) from course_details cd where cd.course_id=c.course_id) as courseCount
from course c
where c.wx_media_id = ${id}
